function remoteKey(name, label) {
    var svg = REMOTE_ICONS[name];
    if (!svg) return '';
    var text = String(label).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
    return '<span class="rkey rkey-' + name + '" role="img" aria-label="' + text + '" title="' + text + '">' + svg + '</span>';
}

function pageSource() { return 'var REMOTE_ICONS=' + JSON.stringify(REMOTE_ICONS) + ';\n' + remoteKey.toString(); }

module.exports = {icons: REMOTE_ICONS, key: remoteKey, pageSource: pageSource};
